#ifndef NTX_SHARE_TRACKERS_H
#define NTX_SHARE_TRACKERS_H

#include <stdint.h>

#include "ntx_https_pins.h"

/* Built-in HTTPS share tracker list (design §6). The table is regenerated by
 * `make pins-update`; --share is gated off below NTX_SHARE_MIN_TRACKERS hosts. */

#define NTX_SHARE_MIN_TRACKERS 2

typedef struct {
    const char *url, *host;
    int npins;
    uint8_t pins[NTX_HTTPS_PIN_MAX][32];
} ntx_share_tracker;

int ntx_share_tracker_count(void);
const ntx_share_tracker *ntx_share_tracker_get(int i);
int ntx_share_available(void); /* count >= NTX_SHARE_MIN_TRACKERS */
void ntx_share_trackers_test_set(const ntx_share_tracker *v, int n); /* n < 0: built-in list */

#endif
